"""Creating and updating the Chromium checkout."""

from __future__ import annotations

import os
import sys
from pathlib import Path
from typing import List

from . import patches
from .layout import Layout
from .process import CommandError, depot_tool, git, run

DEPOT_TOOLS_URL = 'https://chromium.googlesource.com/chromium/tools/depot_tools.git'
CHROMIUM_URL = 'https://chromium.googlesource.com/chromium/src.git'

GCLIENT_TEMPLATE = '''\
# Generated by `strata init`. The src revision is managed by Strata
# (config/chromium_version), so the solution is unmanaged.
solutions = [
  {{
    "name": "src",
    "url": "{url}",
    "managed": False,
    "custom_deps": {{}},
    "custom_vars": {{}},
  }},
]
target_os = {target_os!r}
'''


def host_os() -> str:
  if sys.platform == 'darwin':
    return 'mac'
  if sys.platform == 'win32':
    return 'win'
  return 'linux'


def ensure_depot_tools(layout: Layout) -> None:
  if layout.depot_tools.is_dir():
    return
  layout.chromium_dir.mkdir(parents=True, exist_ok=True)
  run(['git', 'clone', DEPOT_TOOLS_URL, layout.depot_tools], layout.chromium_dir)


def write_gclient(layout: Layout, target_os: List[str]) -> None:
  gclient = layout.chromium_dir / '.gclient'
  if gclient.exists():
    return
  gclient.write_text(GCLIENT_TEMPLATE.format(url=CHROMIUM_URL,
                                             target_os=target_os))


def checkout_version(layout: Layout, version: str) -> None:
  """Shallow-fetches the Chromium tag |version| and checks it out."""
  src = layout.src
  if not (src / '.git').exists():
    src.mkdir(parents=True, exist_ok=True)
    run(['git', 'init', '--quiet'], src)
    run(['git', 'remote', 'add', 'origin', CHROMIUM_URL], src)
  tag = 'refs/tags/' + version
  run(['git', 'fetch', '--depth=1', 'origin', '+%s:%s' % (tag, tag)], src)
  run(['git', 'checkout', '--quiet', '--detach', tag], src)


def link_strata(layout: Layout) -> None:
  """Makes the repository visible to GN as //strata."""
  if layout.in_tree:
    return
  link = layout.src / 'strata'
  if not link.exists():
    if sys.platform == 'win32':
      import _winapi  # Junctions don't need admin rights, unlike symlinks.
      _winapi.CreateJunction(str(layout.root), str(link))
    else:
      link.symlink_to(os.path.relpath(layout.root, layout.src))
  exclude = layout.src / '.git' / 'info' / 'exclude'
  exclude.parent.mkdir(parents=True, exist_ok=True)
  lines = exclude.read_text().splitlines() if exclude.exists() else []
  if '/strata' not in lines:
    exclude.write_text('\n'.join(lines + ['/strata']) + '\n')


def gclient_sync(layout: Layout) -> None:
  env = layout.env()
  run([depot_tool('gclient'), 'sync', '--nohooks', '--no-history', '-D'],
      layout.chromium_dir, env=env)
  run([depot_tool('gclient'), 'runhooks'], layout.chromium_dir, env=env)


def ensure_clean(layout: Layout) -> None:
  """Fails if src has changes that aren't captured in patches/."""
  dirty = patches.changed_files(layout.src, exclude=('strata',))
  if dirty:
    raise CommandError(
        'src has changes that are not in patches/:\n  ' +
        '\n  '.join(dirty[:20]) +
        '\nRun `strata patches export` to keep them, or discard them.')


def init(layout: Layout, target_os: List[str]) -> None:
  ensure_depot_tools(layout)
  write_gclient(layout, target_os)
  checkout_version(layout, layout.chromium_version())
  link_strata(layout)
  gclient_sync(layout)
  failures = patches.apply(layout.patches_dir, layout.src)
  if failures:
    raise CommandError('%d patch(es) failed to apply' % len(failures))


def update(layout: Layout, version: str) -> List[Path]:
  """Moves the checkout to |version|. Returns patches that need fixing."""
  if patches.revert(layout.patches_dir, layout.src):
    raise CommandError('could not revert patches; fix src first')
  ensure_clean(layout)
  checkout_version(layout, version)
  layout.version_file.write_text(version + '\n')
  gclient_sync(layout)
  return patches.apply(layout.patches_dir, layout.src, three_way=True)
